# syntax=docker/dockerfile:1.7
FROM node:24-bookworm-slim AS sdk-build
WORKDIR /src/sdk
COPY sdk/package.json sdk/package-lock.json ./
RUN npm ci --ignore-scripts=false
COPY sdk/ ./
RUN npm run build

FROM node:24-bookworm-slim AS web-build
WORKDIR /src/web
COPY web/package.json web/package-lock.json ./
RUN npm ci --ignore-scripts=false
COPY web/ ./
RUN npm run build
COPY --from=sdk-build /src/sdk/dist/tracker.js /src/web/dist/tracker.js

FROM golang:1.26.7-bookworm AS go-build
WORKDIR /src
COPY go.mod go.sum ./
RUN go mod download
COPY cmd/ cmd/
COPY internal/ internal/
# An empty VERSION leaves the version declared in internal/version alone, so an
# image built straight from the source tree still reports the version it was built
# from. It used to default to "dev", and the profile menu showed that to the
# operator as the service version.
ARG VERSION=
ARG COMMIT=unknown
ARG BUILD_TIME=unknown
RUN CGO_ENABLED=0 GOOS=linux go build -trimpath -ldflags="-s -w ${VERSION:+-X github.com/hkjang/Momento/internal/version.Version=${VERSION}} -X github.com/hkjang/Momento/internal/version.Commit=${COMMIT} -X github.com/hkjang/Momento/internal/version.BuildTime=${BUILD_TIME}" -o /out/momento ./cmd/momento

FROM debian:bookworm-slim
RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates tzdata && rm -rf /var/lib/apt/lists/* && groupadd --system momento && useradd --system --gid momento --home-dir /app momento
WORKDIR /app
COPY --from=go-build /out/momento /app/momento
COPY --from=web-build /src/web/dist /app/web
USER momento
EXPOSE 8080
ENTRYPOINT ["/app/momento"]
# Changelog

## v0.34.58

- **「망 대역 추가」 의 CIDR 칸이 틀린 표기를 보내기 전에 걸러 냅니다.** 앞의 네 릴리스가 고친 것은 **실패한 뒤에 뜨는 문장**이었고, 이번에는 같은 폼에서 그 실패 자체를 없앱니다. 「CIDR」 칸은 콘솔에서 CIDR 을 손으로 적는 유일한 칸인데 「추가」 가 `!form.name || !form.cidr` 로 **빈 칸만** 막아, `10.20.30`(비트 수 없음)·`10.20.30.0/33`(범위 밖)·`10.20.30.0/abc`(숫자 아님)·`1.2.3.4.5/24`(옥텟 5개)는 모두 네트워크를 한 번 왕복하고 서버의 400 `INVALID_CIDR`(`internal/httpapi/admin.go:812` `net.ParseCIDR`)을 받아야 알 수 있었습니다 — **칸 바로 위 placeholder 에 올바른 모양이 이미 떠 있는데도** 그랬습니다. 이제 새 순수 모듈 `web/src/pages/cidrRule.ts` 의 `judgeCIDR` 가 폼에서 판정해 「추가」 를 닫고 왜 막혔는지를 칸 아래에 한국어로 보입니다.
- **안내 문장의 정본을 하나로 모았습니다.** 올바른 표기를 설명하는 문장은 지금까지 `adminErrors.ts` 의 `describeNetworkError` **안에만** 있어서, 사용자는 **틀린 뒤에만** 올바른 표기법을 읽을 수 있었습니다. `cidrRule.ts` 가 그 문장을 `CIDR_RULE` 로 내보내고 폼의 helperText 와 `INVALID_CIDR` 의 Alert 이 같은 상수를 읽습니다 — 두 곳이 같은 말을 하는 것이 누가 양쪽을 다 고치기로 기억하는 일이 아니라 구조상 참입니다(`PASSWORD_RULE` 선례). 칸 아래에는 늘 읽을 거리가 있습니다: 막혔으면 이유, 아니면 알아 둘 것, 그것도 없으면 규칙 자체.
- **화면이 서버보다 좁아지지 않게 했습니다.** 차단은 `net.ParseCIDR` 이 **확실히 거절하는** 값만 합니다 — 화면이 더 엄격해지면 서버가 받아 줄 값을 넣을 방법이 사라집니다. 호스트 비트가 켜진 `10.20.30.1/24` 는 ParseCIDR 이 통과시키므로 막지 않고 오류 색도 쓰지 않으며 계산한 시작 주소만 중립 안내로 보입니다(Postgres `cidr` 컬럼이 이 값을 어떻게 다루는지는 **데이터베이스로 재현하지 못했으므로** 아무 주장도 하지 않습니다). IPv6 본문과 IPv4 주소의 선행 0 도 통과시킵니다. **비트 수의 선행 0**(`/024`·`/00000000024`)은 Go 로 29개 값을 실제로 넣어 보고 ParseCIDR 이 **통과시킨다**는 것을 확인했기에, 정규식으로 모양을 보지 않고 서버의 `dtoi` 와 같이 십진수 **값**으로 읽습니다 — 기억에 기댔으면 바로 여기서 화면이 서버보다 좁아졌을 자리입니다.
- **'막힘' 과 '오류 색' 을 갈라 두었습니다.** `10.20.30` 처럼 아직 적는 중일 수 있는 미완성 입력은 버튼만 닫고 빨간색을 쓰지 않습니다. 폼을 열자마자 빨간 글씨가 보이는 일도 없습니다.
- `web/test/cidrRule.test.mjs` 가 이 성질을 고정합니다(211 → 223건). 순수 함수 테스트에 더해 ① **부분집합 증명** — 890개 생성 코퍼스(중복 제거 888개)를 Go `net.ParseCIDR` 과 `judgeCIDR` 양쪽에 돌려 화면이 막은 727건 중 서버가 받아 줄 값이 하나도 없음을 확인했고(위반 0건), ② **실제 프로덕션 배선** — `npm run build` 의 dist 를 `/api/v1/me`·`/api/v1/sites`·`/api/v1/networks` 를 흉내 낸 임시 서버에 올리고 headless Chrome 으로 `/admin?section=networks` 의 칸을 채워 「추가」 를 눌러 버튼 `disabled`·helperText DOM·`Mui-error` 색·**서버에 도달한 POST 건수**를 읽었습니다(네 값 모두 POST 0건, `10.20.30.1/24` 는 1건이 적은 값 그대로 전송). 변경을 되돌린 대조에서는 같은 하네스가 20건 실패하고 POST 가 5건 도달합니다. `INVALID_CIDR` 문장을 글자 그대로 묶은 기존 단언(`adminErrors.test.mjs:619`)은 한 글자도 고치지 않고 통과합니다.
- 바꾼 것은 프로덕션 3파일과 테스트 1파일입니다. 서버는 손대지 않았습니다(`admin.go` 가 검증의 정본). 설정 화면의 「신뢰할 Reverse Proxy CIDR」 은 다른 엔드포인트의 다른 검사라 포함하지 않았습니다. Go·API 변경과 데이터베이스 마이그레이션은 없습니다.

## v0.34.57

- **Event Schema 를 저장하다 실패하면 무엇을 고칠지 한국어로 말합니다.** 앞의 세 릴리스가 고친 것은 서버 영문이었지만 이번 것은 **브라우저 엔진의 문장**입니다 — 네 폼 중 유일하게 가장 흔한 실패가 서버에 닿지조차 않습니다. 「JSON Schema」 칸은 다섯 줄짜리 자유 입력이고 `save` 뮤테이션이 `mutationFn` **안에서** `JSON.parse(form.schemaText)` 를 평가하므로, 한 글자만 깨져도 요청이 만들어지기 전에 V8 이 던지고 react-query 가 그 **동기** throw 를 `save.error` 에 담아 Alert 이 `Unexpected token '}', "{"properties": }" is not valid JSON` 를 그대로 띄웠습니다. 화면에 자유 입력 칸이 셋인데 엔진의 문장은 그중 어느 것도 가리키지 않았습니다. 서버까지 간 실패도 같았습니다 — `upsertEventDefinition`(`internal/httpapi/admin.go:1395-1446`)이 `INVALID_MODE` 의 영문과 `DEFINITION_SAVE_FAILED` 의 `err.Error()` 를 돌려주므로 pgx 원문이 브라우저까지 흘렀습니다. 이제 `web/src/pages/adminErrors.ts` 의 새 `describeEventDefinitionError` 가 「짝·쉼표를 확인하고 키와 문자열 값은 겹따옴표로 감싸세요, 비울 때는 `{}`」 처럼 고칠 것을 말하고 **어느 칸인지를 이름으로** 가리킵니다. 모르는 코드는 서버 메시지로 되돌아갑니다.
- **JSON 구문 분기는 `switch` 앞에 둡니다.** 이 에러에는 `code` 가 **없어** 코드만 보고 분기하면 `default` 로 떨어져 엔진의 영문이 그대로 나갑니다. 판정은 `error instanceof SyntaxError` 로 하고, 메시지 패턴 `/JSON/` 은 **`code` 가 없을 때만** 보는 보조로 뒀습니다 — 코드가 붙은 서버 거절의 메시지에 'JSON' 이 들어 있어도 구문 분기가 가로채지 않는 것까지 단언합니다.
